(4092562, 584188, 60862, '<td valign="top">Nice idea, but the yellowish color doesn''t work well.  The stripes should be bright white.</td>', 'Nice idea, but the yellowish color doesn''t work well.  The stripes should be bright white.', '2007-09-15 22:50:54.000000', NULL, 1),
(4092564, 584515, 60862, '<td valign="top">Ah, candy within candy within candy (or so it appears).  Great use of this technique!  My favorite of the challenge.</td>', 'Ah, candy within candy within candy (or so it appears).  Great use of this technique!  My favorite of the challenge.', '2007-09-15 22:51:28.000000', NULL, 1),
(4092566, 583523, 60862, '<td valign="top">A little brighter and a little more contrast would help this.  I like the colors and arrangement, but it lacks zing.</td>', 'A little brighter and a little more contrast would help this.  I like the colors and arrangement, but it lacks zing.', '2007-09-15 22:52:35.000000', NULL, 1);
